                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_1" id="ielts_listening_answer_12599_1_0" value="A"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_1" id="ielts_listening_answer_12599_1_1" value="B"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_1" id="ielts_listening_answer_12599_1_2" value="C"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_1" id="ielts_listening_answer_12599_1_3" value="D"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_1" id="ielts_listening_answer_12599_1_4" value="E"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_1" id="ielts_listening_answer_12599_1_5" value="F"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_1" id="ielts_listening_answer_12599_1_6" value="G"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_1" id="ielts_listening_answer_12599_1_7" value="H"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-listening-question-item"><td class="ielts-listening-matching-question-cell"><strong id="ielts-listening-question-number-17" class="ielts-q-badge">17</strong> <span>Bow and arrow display</span></td>
                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_2" id="ielts_listening_answer_12599_2_0" value="A"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_2" id="ielts_listening_answer_12599_2_1" value="B"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_2" id="ielts_listening_answer_12599_2_2" value="C"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_2" id="ielts_listening_answer_12599_2_3" value="D"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_2" id="ielts_listening_answer_12599_2_4" value="E"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_2" id="ielts_listening_answer_12599_2_5" value="F"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_2" id="ielts_listening_answer_12599_2_6" value="G"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_2" id="ielts_listening_answer_12599_2_7" value="H"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-listening-question-item"><td class="ielts-listening-matching-question-cell"><strong id="ielts-listening-question-number-18" class="ielts-q-badge">18</strong> <span>Hunting birds display</span></td>
