-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_3" id="ielts_listening_answer_12599_3_7" value="H"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-listening-question-item"><td class="ielts-listening-matching-question-cell"><strong id="ielts-listening-question-number-19" class="ielts-q-badge">19</strong> <span>Traditional dancing</span></td>
                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_4" id="ielts_listening_answer_12599_4_0" value="A"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_4" id="ielts_listening_answer_12599_4_1" value="B"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_4" id="ielts_listening_answer_12599_4_2" value="C"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_4" id="ielts_listening_answer_12599_4_3" value="D"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_4" id="ielts_listening_answer_12599_4_4" value="E"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_4" id="ielts_listening_answer_12599_4_5" value="F"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_4" id="ielts_listening_answer_12599_4_6" value="G"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_4" id="ielts_listening_answer_12599_4_7" value="H"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-listening-question-item"><td class="ielts-listening-matching-question-cell"><strong id="ielts-listening-question-number-20" class="ielts-q-badge">20</strong> <span>Shop</span></td>
                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_5" id="ielts_listening_answer_12599_5_0" value="A"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_5" id="ielts_listening_answer_12599_5_1" value="B"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_5" id="ielts_listening_answer_12599_5_2" value="C"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_5" id="ielts_listening_answer_12599_5_3" value="D"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_5" id="ielts_listening_answer_12599_5_4" value="E"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_5" id="ielts_listening_answer_12599_5_5" value="F"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_5" id="ielts_listening_answer_12599_5_6" value="G"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_12599_5" id="ielts_listening_answer_12599_5_7" value="H"></td></tr></tbody></table>                                                                                                                                                                                        </div>
